// Data model for the fullscreen Big Ass Flip ceremony.
//
// The x10 gate uses rngWord bit 0. The cut uses the domain-separated BAF
// winner stream (pick key 1 << 17).

import { fetchJSON } from './api.js';
import { ethers } from './contracts.js';
import { normalizeBafDraw } from './baf-draw.js';
import { eligibleBafLeaders, isBafRankEligible } from './baf-leaderboard.js';

const FLIP = 10n ** 18n;
const ENTRIES_PER_TICKET = 4n;
const LOAD_TIMEOUT_MS = 20_000;

function _big(value) {
  try { return BigInt(value ?? 0); } catch (_e) { return 0n; }
}

function _address(value) { return String(value || '').toLowerCase(); }

export const BAF_PRIZE_LANES = Object.freeze([
  Object.freeze({ id: 'leader', label: 'TOP SCORE', share: 10, detail: '#1' }),
  Object.freeze({ id: 'daily', label: 'FINAL-DAY DRAW', share: 5, detail: 'WEIGHTED' }),
  Object.freeze({ id: 'cut', label: 'CUT SURVIVOR', share: 5, detail: '#3 / #4' }),
  // Audit 26ad5863: the far-future draws are gone; the scatter pays 50% + 30% over 48 rounds.
  Object.freeze({ id: 'scatter', label: 'SCATTER', share: 80, detail: '48 ROUNDS' }),
]);

export function bafGateWon(rngWord) {
  if (rngWord == null) return null;
  try { return (BigInt(ethers.keccak256(ethers.AbiCoder.defaultAbiCoder().encode(['uint256','uint256'], [61n, _big(rngWord)]))) & 1n) === 1n; } catch (_e) { return null; }
}

/** Rank 3 or 4 receiving the random leaderboard slice on a winning gate. */
export function bafCutSurvivorRank(rngWord) {
  if (rngWord == null) return null;
  try {
    const hash2 = (a, b) => ethers.keccak256(ethers.AbiCoder.defaultAbiCoder().encode(
      ['uint256', 'uint256'],
      [a, b],
    ));
    const entropy = BigInt(hash2(4n, BigInt(rngWord)));
    return 3 + Number(entropy & 1n);
  } catch (_e) { return null; }
}

export function normalizeBafTopFour(payload, level) {
  return eligibleBafLeaders(payload, level).map((row) => ({
    rank: row.rank,
    player: _address(row.player),
    score: _big(row.score).toString(),
  }));
}

function _rowCount(row) {
  const count = Number(row?.count);
  return Number.isInteger(count) && count > 0 ? count : 1;
}

function _isPrizeHitForRound(row, level, day) {
  const kind = String(row?.awardType || '').toLowerCase();
  const rowLevel = Number(row?.level);
  const sourceLevel = Number(row?.sourceLevel);
  const rowDay = Number(row?.day);

  if (kind === 'eth_baf') return rowLevel === level;
  if (kind === 'tickets_baf') {
    // BAF ticket prizes are emitted at their new target level. sourceLevel is
    // the resolved BAF level in a normal phase and level + 1 in a turbo
    // settlement, so filtering on row.level alone silently drops most of
    // the player-facing ticket outcomes.
    return rowLevel === level || sourceLevel === level || sourceLevel === level + 1;
  }
  if (kind === 'whale_pass_baf') {
    // v77 whale-pass rows deliberately carry level=0. Their indexed day is the
    // only round attribution left on the event.
    return Number.isInteger(day) && Number.isInteger(rowDay) && rowDay === day;
  }
  return false;
}

/** Player-only prize-bearing BAF results, retained as individual reveal cards. */
export function normalizeBafPrizeHits(wins, level, day = null) {
  const lvl = Number(level);
  const resolvedDay = Number(day);
  const hits = [];
  for (const row of Array.isArray(wins) ? wins : []) {
    if (!_isPrizeHitForRound(row, lvl, resolvedDay)) continue;
    const kind = String(row?.awardType || '').toLowerCase();
    const count = _rowCount(row);
    if (kind === 'eth_baf') {
      const amount = _big(row?.amount);
      if (amount > 0n) hits.push({ kind: 'eth', amount: amount.toString(), count });
      continue;
    }
    if (kind === 'tickets_baf') {
      const entries = _big(row?.amount);
      if (entries <= 0n) continue;
      hits.push({
        kind: 'tickets',
        amount: (entries / ENTRIES_PER_TICKET).toString(),
        entries: entries.toString(),
        count,
        level: Number.isInteger(Number(row?.level)) ? Number(row.level) : null,
      });
      continue;
    }
    const halfPassCount = Number(row?.halfPassCount ?? row?.amount ?? 0);
    if (Number.isInteger(halfPassCount) && halfPassCount > 0) {
      hits.push({ kind: 'whale-pass', amount: String(halfPassCount), count });
    }
  }
  return hits;
}

/** Explicit draw slates only: prize history cannot identify losing opponents. */
export function normalizeBafComparisons(groups, player) {
  const viewed = _address(player);
  if (!viewed || !Array.isArray(groups)) return [];
  return groups.flatMap((group, index) => {
    if (!Array.isArray(group?.players) || !group.players.length || group.players.length > 4) return [];
    if (group.players.some((row) => (!row?.player && !row?.empty) || row.score == null)) return [];
    const players = group.players.map((row) => ({
      player: _address(row.player),
      score: _big(row.score).toString(),
      isPlayer: _address(row.player) === viewed,
      empty: row.empty === true,
      placement: [0, 1, 2].includes(row.placement) ? row.placement : null,
      // null means unknown; [] means this entry received no prize.
      prizes: Array.isArray(row.prizes) ? row.prizes.filter((prize) =>
        ['eth', 'tickets', 'whale-pass'].includes(prize?.kind) && _big(prize.amount) > 0n,
      ).map((prize) => ({
        kind: prize.kind, amount: _big(prize.amount).toString(),
        level: prize.level == null ? null : Number(prize.level),
      })) : null,
    })).sort((a, b) => _big(a.score) > _big(b.score) ? -1 : _big(a.score) < _big(b.score) ? 1 : 0)
      .map((row, rank) => ({ ...row, rank: rank + 1 }));
    if (!players.some((row) => row.isPlayer)) return [];
    return [{
      id: String(group.id ?? index + 1),
      round: Number.isInteger(Number(group.round)) ? Number(group.round) : index + 1,
      level: group.level == null ? null : Number(group.level),
      players,
    }];
  });
}

export function buildBafResolutionSnapshot({
  level,
  player,
  metadata,
  leaderboard,
  playerOutcome,
  history,
  draw,
  comparisons,
  consolation = 0,
} = {}) {
  const lvl = Number(level);
  if (!Number.isInteger(lvl) || lvl <= 0 || lvl % 10 !== 0) {
    throw new Error('Invalid BAF resolution level.');
  }
  const status = String(metadata?.status || playerOutcome?.roundStatus || 'open');
  if (!['closed', 'skipped'].includes(status)) {
    throw new Error(`Level ${lvl} BAF is not resolved yet.`);
  }
  const rngWord = metadata?.rngWord == null ? null : String(metadata.rngWord);
  const gateFromWord = bafGateWon(rngWord);
  const gateWon = status === 'closed' ? true : (status === 'skipped' ? false : gateFromWord);
  // The metadata endpoint can deploy a few minutes behind the player and
  // leaderboard endpoints. A closed round still has an honest, useful receipt
  // without that word; only the rank-3/4 cut replay is deferred.
  const survivorRank = gateWon && rngWord != null ? bafCutSurvivorRank(rngWord) : null;
  const cutKnown = !gateWon || survivorRank != null;

  const topFour = normalizeBafTopFour(leaderboard, lvl);
  const viewed = _address(player || playerOutcome?.player);
  // Round-scoped chain awards are complete; the generic wallet history is
  // paginated and can omit an older BAF (or most of a busy round's payouts).
  const wins = Array.isArray(metadata?.wins)
    ? metadata.wins.filter((row) => _address(row.winner) === viewed)
    : history?.wins ?? history;
  const prizeHits = normalizeBafPrizeHits(wins, lvl, metadata?.day);
  const playerAwards = prizeHits.reduce((totals, hit) => {
    const amount = _big(hit.amount);
    // Aggregated feeds may attach count while amount already contains the sum;
    // never multiply the value a second time here.
    if (hit.kind === 'eth') totals.eth += amount;
    if (hit.kind === 'tickets') totals.tickets += amount;
    if (hit.kind === 'whale-pass') totals.whalePassHalves += amount;
    return totals;
  }, { eth: 0n, tickets: 0n, whalePassHalves: 0n });
  const finalDayDraw = normalizeBafDraw(draw, metadata?.day, viewed);
  const rank = Number(playerOutcome?.rank);
  const playerRank = !isBafRankEligible(viewed) ? null
    : topFour.find((entry) => entry.player === viewed)?.rank
      ?? (Number.isInteger(rank) && rank > 0 ? rank : null);
  const leaderSlicePct = gateWon && playerRank === 1
    ? 10
    : (gateWon && playerRank === survivorRank ? 5 : 0);
  const wonAny = gateWon && (
    leaderSlicePct > 0
    || playerAwards.eth > 0n
    || playerAwards.tickets > 0n
    || playerAwards.whalePassHalves > 0n
  );
  const ticketEntries = _big(metadata?.awards?.ticketEntries);

  return {
    level: lvl,
    day: Number.isInteger(Number(metadata?.day)) ? Number(metadata.day) : null,
    status,
    rngWord,
    gateWon,
    cutKnown,
    survivorRank,
    eliminatedCutRank: gateWon && survivorRank != null
      ? (survivorRank === 3 ? 4 : 3)
      : null,
    resolutionDetailsAvailable: metadata?.detailsAvailable !== false,
    estimatedPoolWei: metadata?.estimatedPoolWei == null
      ? null
      : _big(metadata.estimatedPoolWei).toString(),
    topFour,
    comparisons: gateWon ? normalizeBafComparisons(
      comparisons ?? metadata?.comparisons, viewed,
    ) : [],
    comparisonsAvailable: Array.isArray(comparisons ?? metadata?.comparisons),
    comparisonScope: metadata?.comparisonScope ?? null,
    draw: finalDayDraw,
    player: {
      address: viewed || null,
      score: _big(playerOutcome?.score).toString(),
      rank: playerRank,
      totalParticipants: Number.isInteger(Number(playerOutcome?.totalParticipants))
        ? Number(playerOutcome.totalParticipants)
        : null,
      eth: playerAwards.eth.toString(),
      tickets: playerAwards.tickets.toString(),
      whalePassHalves: playerAwards.whalePassHalves.toString(),
      prizeHits,
      consolation: _big(consolation).toString(),
      leaderSlicePct,
      wonAny,
    },
    awards: {
      ethCount: Number(metadata?.awards?.ethCount || 0),
      ethUnique: Number(metadata?.awards?.ethUnique || 0),
      ethTotal: _big(metadata?.awards?.ethTotal).toString(),
      ticketCount: Number(metadata?.awards?.ticketCount || 0),
      ticketUnique: Number(metadata?.awards?.ticketUnique || 0),
      ticketEntries: ticketEntries.toString(),
      tickets: (ticketEntries / ENTRIES_PER_TICKET).toString(),
    },
    prizeLanes: BAF_PRIZE_LANES.map((lane) => ({ ...lane })),
  };
}

let _fetch = fetchJSON;

function _fetchWithin(path, signal) {
  const controller = new AbortController();
  let timer = null;
  const abort = () => controller.abort(signal.reason);
  const timeout = new Promise((_resolve, reject) => {
    controller.signal.addEventListener('abort', () => reject(controller.signal.reason), { once: true });
    timer = setTimeout(() => controller.abort(new Error('The BAF draw took too long to load. Try again.')), LOAD_TIMEOUT_MS);
    try { timer?.unref?.(); } catch (_e) { /* browser timer */ }
  });
  if (signal?.aborted) abort();
  else signal?.addEventListener('abort', abort, { once: true });
  return Promise.race([
    Promise.resolve().then(() => {
      controller.signal.throwIfAborted();
      return _fetch(path, { signal: controller.signal, priority: 'interaction', force: true });
    }),
    timeout,
  ]).finally(() => {
    if (timer != null) clearTimeout(timer);
    signal?.removeEventListener('abort', abort);
  });
}

export async function loadBafResolutionSnapshot({
  level,
  player,
  consolation = 0,
  playerOutcome: seededPlayerOutcome = null,
  history: seededHistory = null,
  signal,
} = {}) {
  const lvl = Number(level);
  const address = _address(player);
  if (!address) throw new Error('A player address is required for the BAF draw.');
  const encodedLevel = encodeURIComponent(lvl);
  const encodedPlayer = encodeURIComponent(address);
  const metadataRequest = _fetchWithin(`/game/baf/${encodedLevel}/resolution`, signal);
  const drawRequest = metadataRequest.then((metadata) => {
    const day = Number(metadata?.day);
    if (!Number.isInteger(day) || day <= 0) return null;
    const word = metadata?.rngWord == null ? '' : `&rngWord=${encodeURIComponent(metadata.rngWord)}`;
    return _fetchWithin(
      `/leaderboards/coinflip?day=${encodeURIComponent(day)}&player=${encodedPlayer}${word}`,
      signal,
    );
  });
  const [metadataResult, leaderboardResult, playerResult, historyResult, drawResult] = await Promise.allSettled([
    metadataRequest,
    _fetchWithin(`/leaderboards/baf?level=${encodedLevel}`, signal),
    _fetchWithin(`/player/${encodedPlayer}/baf?level=${encodedLevel}`, signal),
    _fetchWithin(`/player/${encodedPlayer}/jackpot-history`, signal),
    drawRequest,
  ]);

  signal?.throwIfAborted();
  const playerOutcome = playerResult.status === 'fulfilled' ? playerResult.value : seededPlayerOutcome;
  if (!playerOutcome) {
    throw new Error(`Level ${lvl} BAF final is still syncing. Try again shortly.`);
  }

  const terminalStatus = ['closed', 'skipped'].includes(String(playerOutcome?.roundStatus || ''))
    ? String(playerOutcome.roundStatus)
    : null;
  const fetchedMetadata = metadataResult.status === 'fulfilled'
    && metadataResult.value && typeof metadataResult.value === 'object'
    ? metadataResult.value
    : null;
  const metadataStatus = String(fetchedMetadata?.status || '');
  const metadata = {
    ...(fetchedMetadata || {}),
    status: terminalStatus || metadataStatus || String(playerOutcome?.roundStatus || 'open'),
    detailsAvailable: fetchedMetadata != null,
  };
  const leaderboard = leaderboardResult.status === 'fulfilled'
    ? leaderboardResult.value
    : { entries: [] };
  const history = historyResult.status === 'fulfilled'
    ? historyResult.value
    : seededHistory ?? { wins: [] };
  const draw = drawResult.status === 'fulfilled' ? drawResult.value : null;

  const snapshot = buildBafResolutionSnapshot({
    level: lvl,
    player: address,
    metadata,
    leaderboard,
    playerOutcome,
    history,
    draw,
    consolation,
  });
  // A successful request can still contain an earlier, unfinished chain view.
  // Keep retrying while Pending rather than permanently caching missing draws.
  snapshot.preparationComplete = [metadataResult, leaderboardResult, playerResult, drawResult]
    .every(result => result.status === 'fulfilled')
    && ['closed', 'skipped'].includes(metadataStatus)
    && metadataStatus === snapshot.status
    && Number.isInteger(snapshot.day) && snapshot.day > 0
    && snapshot.rngWord != null && snapshot.cutKnown
    && Array.isArray(leaderboard?.entries)
    && (Array.isArray(fetchedMetadata?.wins) || historyResult.status === 'fulfilled')
    && draw != null && snapshot.draw.totalWeight != null && snapshot.draw.player != null
    && (!snapshot.gateWon || (snapshot.draw.winnerKnown && snapshot.comparisonsAvailable));
  return snapshot;
}

export function formatBafResolutionScore(raw) {
  const whole = _big(raw) / FLIP;
  return whole.toLocaleString('en-US');
}

export function __setBafResolutionFetcherForTest(fetcher) {
  _fetch = typeof fetcher === 'function' ? fetcher : fetchJSON;
}

export function __resetBafResolutionFetcherForTest() {
  _fetch = fetchJSON;
}
